"""Explain KCSAN counters, value-change states and reporting roles."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1701': ('도서관에서 지금 빌려 간 책 수와 오늘까지 빌려 준 횟수는 달라요. 책을 반납하면 지금 대출 수는 줄지만 이미 빌려 준 횟수는 사라지지 않아요.', '현재 사용량과 누적 사건 수를 구별하고 통계 갱신 위치를 이해합니다.', '감시 기록을 3개 설치한 뒤 1개 해제한 예에서 현재 사용2·누적 설치3을 적으세요.', ['KCSAN은 메모리를 여러 실행 흐름이 함께 다룰 때 생기는 충돌을 찾는 도구예요. watchpoint는 살펴볼 접근을 적은 감시 기록이고 counter는 정해진 사건이나 양을 세는 숫자예요. 숫자를 읽기 전에 무엇을 세는지 먼저 확인해야 해요.', 'USED_WATCHPOINTS는 지금 사용 중인 감시 기록 수예요. SETUP_WATCHPOINTS는 지금까지 설치한 감시 기록의 누적 수예요. 예를 들어 처음 둘 다 0이고 3개를 설치한 뒤 1개를 해제했다면 현재 사용은 2, 누적 설치는 3이에요. 해제했다고 과거 설치 사실까지 없어지지는 않아요.', '헤더의 enum은 통계 항목에 이름과 번호를 붙인 목록이에요. 실제 항목은 아홉 개예요. 현재 사용량·누적 설치량 외에도 데이터 충돌, 약속 검사 실패, 빈자리 부족, 보고 경쟁, 쓴 주체 미상, 기록으로 표현 불가, 압축 때문에 생긴 잘못된 후보를 각각 세어요.', '마지막 COUNT는 열 번째 종류의 사건이 아니에요. 통계 항목이 몇 개인지 나타내어 배열 길이에 써요. 배열은 같은 종류의 칸을 번호 순서로 모은 것이에요. extern 선언은 통계 배열이 다른 곳에 정의되어 있고 여기서 그 이름을 쓸 수 있음을 알려요.', '통계 칸은 atomic_long_t 형식으로 선언돼요. 여러 실행 흐름이 함께 숫자를 고칠 때 원자 연산으로 다루기 위한 형식이에요. 단, 배열 전체를 한 번에 읽었다고 모든 칸이 정확히 같은 순간의 사진이 된다는 뜻은 아니에요. 통계는 debugfs라는 커널 진단용 파일 인터페이스에 표시돼요.', '원문은 통계를 slow path에서만 바꾸라고 설명해요. slow path는 추가 처리가 필요한 경로이고 fast path는 자주 실행되는 짧은 처리 경로예요. 매번 자주 지나는 길에 불필요한 통계 갱신까지 넣으면 검사 비용이 커질 수 있어요. 이 헤더는 선언이며 실제 숫자를 바꾸는 위치는 구현에서 따로 확인해요.'], [('USED와 SETUP은 무엇이 다른가요?', ['둘 다 지금 사용하는 메모리의 바이트 수예요', 'USED는 현재 사용 중인 기록 수, SETUP은 누적 설치 수예요'], '정답은 두 번째예요. 3개 설치 후 1개 해제한 예에서는 USED=2, SETUP=3이에요. 둘은 같은 단위의 기록을 보더라도 현재 상태와 과거 누적을 다르게 세어요.'), ('원문은 통계 숫자를 어느 경로에서 바꾸라고 하나요?', ['추가 처리를 하는 slow path예요', '모든 fast path의 바이트 접근마다 무조건 바꿔요'], '정답은 첫 번째예요. 자주 실행되는 짧은 경로에 통계 갱신 비용을 계속 더하지 않으려는 구분이에요. slow path라는 말이 일부러 시간을 끌라는 뜻은 아니에요.')]), 'os1702': ('한 사건 때문에 경보기 두 개가 울리면 경보 횟수는 둘일 수 있어요. 그렇다고 서로 다른 사건이 반드시 두 개인 것은 아니에요.', '통계가 세는 단위를 구별하고 서로 다른 실패 원인을 설명합니다.', '약속 검사 A와 B가 한 번 충돌한 그림에 실패 기록2·서로 다른 버그 수는 이 숫자만으로 모름을 적으세요.', ['통계 숫자를 모두 더해 서로 다른 버그 개수라고 부르면 틀릴 수 있어요. 버그는 프로그램의 잘못이고 통계는 정해진 사건이 몇 번 일어났는지 세는 값이에요. 한 잘못이 여러 번 발생하거나 한 충돌의 양쪽이 따로 세어질 수 있어요.', 'ASSERT는 지켜져야 할 약속을 검사하는 표시예요. ASSERT_FAILURES는 충돌로 약속 검사가 실패한 횟수예요. 원문은 서로 충돌한 양쪽 접근이 모두 ASSERT라면 두 쪽 모두 센다고 설명해요. 한 충돌에서 두 실패가 기록될 수 있으므로 반드시 하나라고 생각하면 안 돼요.', 'REPORT_RACES는 감시 기록을 확인하는 실행 흐름끼리 경쟁한 상황을 세어요. thread는 작업을 진행하는 실행 흐름이에요. 원문 설명에서는 이런 경쟁 중 하나만 보고돼요. 경쟁을 센 값과 실제 출력된 보고 수를 같은 숫자라고 가정하지 마세요.', 'NO_CAPACITY는 쓸 감시 기록 자리가 없는 경우예요. 서랍이 꽉 차서 새 카드를 넣을 수 없는 상황과 비슷해요. UNENCODABLE_ACCESSES는 접근 정보를 유효한 감시 기록 모양으로 담을 수 없는 경우예요. 카드의 길이 칸에 너무 큰 값을 적을 수 없는 상황과 비교할 수 있어요.', 'ENCODING_FALSE_POSITIVES는 주소를 줄여 담는 과정 때문에 실제로 맞지 않는 접근이 후보로 잡힌 경우예요. 번호 끝자리만 같아서 다른 사람을 같은 사람 후보로 고른 것과 비슷해요. 압축 후보와 실제 충돌을 구별하는 추가 확인이 필요해요.', '따라서 통계를 볼 때는 항목별로 무엇을 세는지 적어 보세요. 약속 검사 실패, 빈자리 부족, 표현 불가, 보고 경쟁은 서로 다른 현상이에요. 이 수업은 헤더의 항목 의미를 설명하며 실제 보고 횟수를 실행해 측정했다는 뜻은 아니에요.'], [('서로 충돌한 두 접근이 모두 ASSERT이면 실패 통계는 반드시 1인가요?', ['네. 모든 통계는 서로 다른 버그 수만 세어요', '아니요. 양쪽 실패를 모두 셀 수 있어요'], '정답은 두 번째예요. 원문은 이런 경우 양쪽 모두 센다고 설명해요. 한 충돌에서 실패 둘이 나올 수 있으므로 숫자 2를 곧바로 서로 다른 버그 2개로 바꾸어 읽으면 안 돼요.'), ('NO_CAPACITY와 UNENCODABLE은 같은 이유로 실패한 것인가요?', ['아니요. 자리가 없는 것과 기록 형식으로 표현할 수 없는 것은 달라요', '네. 둘 다 주소가 0이라는 뜻뿐이에요'], '정답은 첫 번째예요. 앞은 감시 기록 자원의 부족, 뒤는 접근 정보를 기록으로 담을 수 없는 문제예요. 원인이 다르므로 항목도 나누어 세어요.')]), 'os1703': ('변화를 못 봤다는 말과 보고하면 안 된다는 말은 달라요. 관찰한 사실과 그 사실을 어떻게 처리할지 두 가지를 함께 기록해야 할 때가 있어요.', '값 변화의 세 상태가 관찰과 보고 판단을 함께 표현함을 이해합니다.', 'MAYBE·FALSE·TRUE 세 칸을 만들고 변화 관찰 여부와 보고 판단을 각각 적으세요.', ['KCSAN은 메모리 접근을 살펴보면서 값이 바뀌었는지도 참고해요. kcsan_value_change는 그 결과를 MAYBE, FALSE, TRUE 세 이름으로 나눠요. 이런 세 상태 구분을 tri-state라고 해요. 단순히 예·아니요 두 칸으로는 담기 어려운 차이가 있어요.', 'MAYBE는 값이 변하는 것을 관찰하지 못했지만 설정에 따라 충돌을 보고할 수 있는 상태예요. 관찰하지 못했다는 것만으로 모든 충돌 가능성이 사라지는 것은 아니에요. 이 이름에는 보고 여부를 추가로 판단할 여지가 남아 있어요.', 'FALSE는 값 변화를 관찰하지 않았고 이 판단에서는 그 충돌을 보고하는 것이 부적절한 상태예요. MAYBE와 둘 다 변화 미관찰이라는 점은 같지만 보고 판단이 달라요. 둘을 하나로 합치면 보고할 수 있는 경우와 보고하면 안 되는 경우의 차이를 잃어요.', 'TRUE는 값의 변화가 관찰된 상태이고 이 상태의 설명은 충돌을 보고해야 한다는 뜻이에요. 예를 들어 관찰한 값이 앞에서는 7, 뒤에서는 9였다면 값이 달라진 것을 볼 수 있어요. 다만 전체 보고 과정의 다른 필터까지 모두 무조건 통과한다는 보증으로 넓혀 읽지는 마세요.', '왜 참·거짓 하나로 줄이지 않을까요? 변화 봄만 true, 못 봄은 모두 false로 쓰면 MAYBE와 FALSE를 구별할 수 없어요. 관찰과 보고 적합성을 함께 담는 이름이므로 세 칸을 유지해요. 앞뒤 값이 같았다는 관찰과 중간에 어떤 일도 없었다는 확정도 구별해야 해요.', 'enum은 이름에 정수 번호를 붙이는 C 문법이에요. 여기서는 MAYBE·FALSE·TRUE 순서로 0·1·2예요. FALSE라는 이름의 번호가 1이라고 해서 일반 bool의 참처럼 해석하면 안 돼요. 이 enum의 이름과 의미로 비교해야 하며 번호를 위험도 점수처럼 읽어서도 안 돼요.'], [('MAYBE와 FALSE는 보고 판단이 같은가요?', ['네. 둘 다 무조건 보고하면 안 돼요', '아니요. MAYBE는 설정에 따라 보고할 수 있고 FALSE는 보고가 부적절해요'], '정답은 두 번째예요. 둘 다 변화를 관찰하지 못했다는 점은 같지만 처리 판단이 달라요. 세 상태를 둘로 줄이면 이 차이가 사라져요.'), ('TRUE는 어떤 관찰을 뜻하나요?', ['값이 변한 것을 관찰했어요', '값이 변했는지 모르는 상태예요'], '정답은 첫 번째예요. 원문은 값의 변화가 관찰됐다고 설명해요. MAYBE와 구별하고, enum의 숫자 크기가 아니라 이름에 정해진 뜻을 읽어야 해요.')]), 'os1704': ('두 사람이 같은 공책을 다룬 일을 설명하려면 양쪽의 메모가 필요해요. 한 사람은 자기 일을 적어 전달하고 다른 사람은 두 기록을 모아 보고서를 만들어요.', '정보를 전달하는 실행 흐름과 보고를 담당하는 실행 흐름을 구별합니다.', 'A가 감시 기록 설치 → B가 맞는 기록 소비·set_info → A가 소비 확인·known_origin 순서로 시간선을 그리세요.', ['여기서 thread는 작업을 진행하는 실행 흐름이에요. A와 B라는 두 흐름을 생각해 보세요. A가 자기 메모리 접근을 감시할 기록을 설치하고, B가 관련 접근을 하다가 그 기록을 발견하는 상황이에요.', 'B가 감시 기록을 hit하고 consume한다는 말은 맞는 기록을 찾아 소비된 상태로 바꿨다는 뜻이에요. 여기서 소비는 메모리의 실제 데이터를 지워 없앤다는 뜻이 아니에요. 감시 기록을 처리한 상태를 가리켜요.', 'kcsan_report_set_info는 이런 B가 자기 접근 정보를 남기는 인터페이스예요. set_info는 정보를 설정한다는 이름이에요. 헤더는 이 단계에서 아직 보고를 출력하지 않는다고 명시해요. 정보를 남기는 일과 전체 보고서를 출력하는 일을 나눈 것이에요.', '전달하는 ptr는 접근 주소, size는 바이트 길이, access_type은 읽기·쓰기 같은 접근 종류예요. ip는 여기서 실행 코드의 위치 정보이며 인터넷 주소라는 뜻이 아니에요. watchpoint_idx는 어느 감시 기록 자리와 연결된 정보인지 나타내는 번호예요.', 'A가 자기가 설치한 감시 기록이 소비됐음을 관찰하면 kcsan_report_known_origin 쪽에서 상대가 남긴 정보를 이용해 보고해요. known_origin은 상대 접근의 정보를 아는 경우의 보고 경로예요. B의 정보와 A 자신의 접근 정보를 함께 다뤄야 어떤 접근끼리 충돌했는지 설명할 수 있어요.', '이 수업은 헤더가 정한 두 역할을 따라가는 것이에요. 실제 정보 저장·동기화·보고 필터의 세부 구현은 report.c에서 추가로 읽어야 해요. 함수 두 개를 아무 순서로나 부르면 안전한 전달이 완성된다고 생각하면 안 돼요. 지정한 역할과 호출 흐름을 지키는 것이 중요해요.'], [('set_info를 부르는 순간 전체 보고서가 바로 출력되나요?', ['네. 언제나 즉시 전체 보고서를 출력해요', '아니요. 보고할 쪽이 사용할 접근 정보를 먼저 남겨요'], '정답은 두 번째예요. 원문은 아직 보고를 출력하지 않는다고 말해요. B가 정보를 전달하는 단계와 A가 그 정보를 이용해 보고하는 단계를 구별하세요.'), ('known_origin은 어떤 역할의 실행 흐름에서 호출하나요?', ['자기가 설치한 감시 기록이 소비됐음을 관찰한 쪽이에요', '시스템의 init 작업 하나에서만 호출해요'], '정답은 첫 번째예요. 예시의 A가 그 역할이에요. A는 상대 B가 남긴 접근 정보를 이용하며, 헤더는 init 작업만 호출한다고 제한하지 않아요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_421.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
